"""Startup inventory, repeat layout-4 disposal and CPU baseline for next measured work."""
import pathlib,json,subprocess,hashlib
from playwright.sync_api import sync_playwright
ROOT=pathlib.Path(__file__).resolve().parents[2];OUT=ROOT/'docs/adventures-v4';result={'environment':'Managed Chromium SwiftShader. Resource counts and CPU wall times, not physical device FPS or thermal results.','repositoryHead':subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip(),'checks':[]}
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox','--use-angle=swiftshader','--enable-unsafe-swiftshader']);g=b.new_page(viewport={'width':640,'height':400});g.set_default_timeout(120000);g.add_init_script("localStorage.setItem('blockworld-adventures-controls-v2',JSON.stringify({quality:'gentle',running:false}))");g.goto('http://127.0.0.1:5175/adventures.html?test=1');g.wait_for_function('window.adventure?.ready');g.locator('#enter').click();g.evaluate('window.requestAnimationFrame=()=>0');g.wait_for_timeout(100)
 result['startupResources']=g.evaluate("performance.getEntriesByType('resource').filter(r=>!r.name.startsWith('blob:')).map(r=>({name:r.name.split('/').pop(),bytes:r.encodedBodySize}))");result['startupBytes']=sum(r['bytes']for r in result['startupResources']);samples=[]
 for i in range(12):
  g.evaluate("adventure.session.create('vale')");g.evaluate("adventure.view('lodge')");samples.append(g.evaluate('adventure.stats()'))
 result['newWorldReplacements']=samples;assert max(s['geometries']for s in samples[2:])-min(s['geometries']for s in samples[2:])<=1;assert max(s['textures']for s in samples)<=16;result['checks'].append({'name':'12 new lodge-world replacements plateau after warmup','passed':True})
 result['cpuBaseline']=g.evaluate("""()=>{const g=adventure.game;g.debugCamera=false;Object.assign(g.player,{x:105,z:16,y:0});g.velocity.set(0,0);const trials=[];for(let j=0;j<5;j++){let t=performance.now();for(let i=0;i<500;i++)g.cameraUpdate(1/60);const cameraMs=performance.now()-t;t=performance.now();for(let i=0;i<600;i++)g.update(1/60,{x:0,z:0,run:false});trials.push({camera500Ms:cameraMs,motion600Ms:performance.now()-t});}return{bodies:g.obstacles().length,trials};}""");b.close()
result['sourceFileHashes']={str(f.relative_to(ROOT)):hashlib.sha256(f.read_bytes()).hexdigest()for f in (ROOT/'src/adventures').glob('*')if f.is_file()};(OUT/'profile-release.json').write_text(json.dumps(result,indent=2)+'\n');print('Startup bytes',result['startupBytes'],'replacement geometry/texture counts',[(s['geometries'],s['textures'])for s in samples],'CPU',result['cpuBaseline'])
